/* OrientaSaúde — bandeiras gráficas embutidas: independentes do suporte a emoji do sistema.
 * Ícones rasterizados de Noto Color Emoji (SIL Open Font License 1.1); nenhuma fonte é distribuída.
 * Seletor compartilhado com suporte a teclado, leitores de tela e alteração de idioma já existente.
 */
(() => {
'use strict';
const images={"pt-BR":"data:image/png;base64,","es":"data:image/png;base64,","en":"data:image/png;base64,","ja":"data:image/png;base64,","ar":"data:image/png;base64,","zh-CN":"data:image/png;base64,","ko":"data:image/png;base64,","ht":"data:image/png;base64,"};
const IDS=new Set(['app-language','tips-lang','spec-lang','br-language','br-units-language']);
const pack=window.OrientaLanguagePack;
if(!pack || !Array.isArray(pack.options))return;
let opened=null;
const flag=(code)=>{
 const img=document.createElement('img');
 img.className='flag-picker-icon';img.alt='';img.loading='eager';
 img.src=images[code]||images['pt-BR'];
 img.width=25;img.height=19;img.draggable=false;
 return img;
};
const selectedData=select=>pack.options.find(x=>x.code===select.value)||pack.options[0];
const triggerName=select=>{
 let descriptor=select.getAttribute('aria-label') || '';
 if(!descriptor){const label=document.querySelector('label[for="'+select.id+'"]');descriptor=label?.textContent?.trim()||'';}
 return descriptor || 'Idioma / Language';
};
function hide(){
 if(!opened)return;
 const {menu,trigger,select}=opened;
 opened=null;
 menu.remove();
 if(trigger.isConnected){trigger.setAttribute('aria-expanded','false')}
}
function createMenu(state){
 const {select,trigger}=state;
 const menu=document.createElement('div');
 menu.className='flag-picker-menu';menu.id='flag-list-'+select.id;menu.setAttribute('role','menu');
 menu.setAttribute('aria-label',triggerName(select));
 let buttons=[];
 for(const item of pack.options){
   const option=document.createElement('button');option.type='button';option.className='flag-picker-option';
   option.setAttribute('role','menuitemradio');option.setAttribute('aria-checked',String(item.code===select.value));
   option.dataset.value=item.code;
   option.append(flag(item.code));
   const native=document.createElement('span');native.className='flag-picker-option-name';native.textContent=item.native;
   option.append(native);
   if(item.code===select.value){const chosen=document.createElement('span');chosen.className='flag-picker-check';chosen.textContent='✓';chosen.setAttribute('aria-hidden','true');option.append(chosen)}
   option.addEventListener('click',e=>{
     e.stopPropagation();e.preventDefault();
     hide();
     if(select.value!==item.code){
       select.value=item.code;
       state.update();
       select.dispatchEvent(new Event('change',{bubbles:true}));
     }
     else trigger.focus();
   });
   option.addEventListener('keydown',e=>{
     const i=buttons.indexOf(option);
     if(e.key==='ArrowDown'||e.key==='ArrowUp'){
       e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();
     }else if(e.key==='Home'){e.preventDefault();buttons[0]?.focus()}
     else if(e.key==='End'){e.preventDefault();buttons[buttons.length-1]?.focus()}
     else if(e.key==='Escape'){e.preventDefault();hide();trigger.focus()}
     else if(e.key==='Tab')hide();
   });
   menu.append(option);buttons.push(option);
 }
 return {menu,buttons};
}
function open(state){
 if(opened?.select===state.select){hide();return}
 hide();
 const {menu,buttons}=createMenu(state);
 document.body.append(menu);
 const rect=state.trigger.getBoundingClientRect();
 const desiredWidth=Math.min(290,window.innerWidth-20);
 menu.style.width=Math.max(Math.min(rect.width+65,desiredWidth),Math.min(224,desiredWidth))+'px';
 const w=menu.getBoundingClientRect().width;
 const h=menu.getBoundingClientRect().height;
 const x=Math.min(Math.max(10,rect.right-w),Math.max(10,window.innerWidth-w-10));
 const freeBottom=window.innerHeight-rect.bottom-10;
 const freeTop=rect.top-10;
 const top=freeBottom<Math.min(h,300)&&freeTop>freeBottom? Math.max(8,rect.top-Math.min(h,freeTop)-7):rect.bottom+7;
 menu.style.left=x+'px';menu.style.top=top+'px';
 menu.style.maxHeight=Math.max(150,Math.min(window.innerHeight-18,top<rect.top?freeTop:freeBottom))+'px';
 state.trigger.setAttribute('aria-expanded','true');opened={...state,menu};
 const index=pack.options.findIndex(x=>x.code===state.select.value);
 buttons[Math.max(index,0)]?.focus();
}
function enhance(select){
 if(select.dataset.flagPickerReady || !IDS.has(select.id))return;
 select.dataset.flagPickerReady='1';
 const wrapper=document.createElement('span');wrapper.className='flag-picker';
 const trigger=document.createElement('button');trigger.type='button';trigger.className='flag-picker-trigger';
 trigger.setAttribute('aria-haspopup','menu');trigger.setAttribute('aria-expanded','false');
 trigger.setAttribute('aria-label',triggerName(select));
 const icon=flag(select.value);
 const text=document.createElement('span');text.className='flag-picker-name';
 const chevron=document.createElement('span');chevron.className='flag-picker-chevron';chevron.setAttribute('aria-hidden','true');
 trigger.append(icon,text,chevron);
 wrapper.append(trigger);select.insertAdjacentElement('afterend',wrapper);
 select.classList.add('flag-picker-native');select.tabIndex=-1;select.setAttribute('aria-hidden','true');
 const state={select,trigger,update(){const item=selectedData(select);icon.src=images[item.code]||images['pt-BR'];text.textContent=item.native;trigger.setAttribute('aria-label',triggerName(select)+': '+item.native)}};
 state.update();
 trigger.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();open(state)});
 trigger.addEventListener('keydown',e=>{
 if(e.key==='ArrowDown'||e.key==='ArrowUp'||e.key==='Enter'||e.key===' '){e.preventDefault();open(state)}
 else if(e.key==='Escape'){hide()}
 });
 select.addEventListener('change',state.update);
}
function scan(){
 if(opened&&!opened.select.isConnected)hide();
 for(const id of IDS){const select=document.getElementById(id);if(select)enhance(select)}
}
document.addEventListener('pointerdown',event=>{if(opened&&!opened.menu.contains(event.target)&&!opened.trigger.contains(event.target))hide()},true);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&opened){const trigger=opened.trigger;hide();trigger.focus()}});
window.addEventListener('resize',hide);
window.addEventListener('scroll',hide,true);
const observer=new MutationObserver(scan);
observer.observe(document.documentElement,{subtree:true,childList:true});
scan();
})();